<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>انتخاب صندلی | سینماپلاس</title><link rel="stylesheet" href="/css/cinema.css"></head><body><header class="nav"><a class="brand" href="/">سینما<span>پلاس</span></a><div class="steps"><b>۱ انتخاب صندلی</b><span>۲ اطلاعات و پرداخت</span><span>۳ تأیید نهایی</span></div></header><main class="container"><div class="booking-layout"><section><div class="booking-meta"><h1>{{ $show->event->title }}</h1><p>{{ $show->venue->name }} · {{ jdate($show->starts_at)->format('Y/m/d') }} · {{ $show->starts_at->format('H:i') }}</p></div><div class="screen">پرده نمایش</div><form method="post" action="{{ route('booking.checkout',$show) }}" id="seat-form">@csrf<div class="seat-map">@foreach($seats->groupBy('row_label') as $row=>$rowSeats)<div class="seat-row"><label>{{ $row }}</label>@foreach($rowSeats as $seat)<label class="seat {{ $seat->type==='vip'?'vip':'' }} {{ $taken->contains($seat->id)?'taken':'' }}"><input type="checkbox" name="seats[]" value="{{ $seat->id }}" {{ $taken->contains($seat->id)?'disabled':'' }} data-price="{{ $seat->type==='vip'&&$show->vip_price?$show->vip_price:$show->price }}"><span>{{ $seat->number }}</span></label>@endforeach</div>@endforeach</div><div class="legend"><span><i class="free"></i>آزاد</span><span><i class="selected"></i>انتخاب‌شده</span><span><i class="taken-dot"></i>رزروشده</span><span><i class="vip-dot"></i>VIP</span></div></section><aside class="summary"><h2>خلاصه سفارش</h2><p>{{ $show->venue->name }}</p><div id="selected-list" class="muted">هنوز صندلی انتخاب نشده</div><hr><div class="total"><span>مجموع</span><strong id="total">۰ تومان</strong></div><button class="primary full" type="submit">ادامه پرداخت 🔒</button><small>در محیط واقعی، این مرحله به درگاه پرداخت متصل می‌شود.</small></aside></div></main><script>const checks=[...document.querySelectorAll('input[type=checkbox]')],total=document.querySelector('#total'),list=document.querySelector('#selected-list');function update(){let on=checks.filter(x=>x.checked),sum=on.reduce((a,x)=>a+Number(x.dataset.price),0);total.textContent=new Intl.NumberFormat('fa-IR').format(sum)+' تومان';list.textContent=on.length?on.length+' صندلی انتخاب شده':'هنوز صندلی انتخاب نشده'}checks.forEach(x=>x.addEventListener('change',update));</script></body></html>
